window.STORY_CHAPTERS["c96d1451cb147a791"]={"id":"c96d1451cb147a791","lines":[{"uid":"talk.ch22_2_1101#originalText","id":"talk.ch22_2_1101","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"谢谢各位在百忙之中抽空来到这里。","en":"Thank you for taking time out of your busy schedules.","ja":"お忙しい中、お集まり頂きましてありがとうございます"},"kind":"dialogue"},{"uid":"talk.ch22_2_1102#originalText","id":"talk.ch22_2_1102","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"今天本机构将要发表世界第一个真正泛用人工智能的诞生。","en":"Today, we're announcing the birth of the world's first true artificial general intelligence.","ja":"本日、当機構は、世界で初となる真正汎用人工知能の誕生を発表させて頂きます"},"kind":"dialogue"},{"uid":"talk.ch22_2_1103#originalText","id":"talk.ch22_2_1103","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"那就让我为各位介绍──《爱丽丝》。","en":"And now, allow me to introduce... Alice.","ja":"それでは、紹介いたします……《アリス》"},"kind":"dialogue"},{"uid":"talk.ch22_2_1104#originalText","id":"talk.ch22_2_1104","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"现实世界的各位，初次见面。我的名字是爱丽丝。","en":"People of the real world, I'm pleased to meet you. My name is Alice.","ja":"リアルワールドの皆さん、はじめまして私の名前はアリス"},"kind":"dialogue"},{"uid":"talk.ch22_2_1105#originalText","id":"talk.ch22_2_1105","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"爱丽丝‧辛赛西斯‧萨蒂。","en":"Alice Synthesis Thirty.","ja":"アリス・シンセシス・サーティです"},"kind":"dialogue"},{"uid":"talk.ch22_2_1106#originalText","id":"talk.ch22_2_1106","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"那……那是我们学校的制服！！","en":"Ooh! That's our school uniform!","ja":"あっ……あれ、うちの制服!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_1107#originalText","id":"talk.ch22_2_1107","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"好像是她本人这么要求的。","en":"I heard she requested it.","ja":"本人が希望したらしいよ"},"kind":"dialogue"},{"uid":"talk.ch22_2_1108#originalText","id":"talk.ch22_2_1108","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"她说想穿和前来救援人界守备军的众人一样的骑士团服装。","en":"The same uniform as the order of knights who came to the aid of the Human Guardian Army.","ja":"人界守備軍の救援に来てくれた皆さんと同じ騎士団の服がいい、って"},"kind":"dialogue"},{"uid":"talk.ch22_2_1109#originalText","id":"talk.ch22_2_1109","speaker":{"cn":"里香","en":"Rika","ja":"里香"},"text":{"cn":"不过她原本最想穿的是和Underworld一样的纯金盔甲。","en":"Although her first choice was the same gold armor she wore over there.","ja":"第一希望は、向こうで着てたのと同じ純金のアーマーだったみたいだけど"},"kind":"dialogue"},{"uid":"talk.ch22_2_1110#originalText","id":"talk.ch22_2_1110","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"就算是RATH也无法准备那种服装吧～","en":"Not even Rath could afford that, could they?","ja":"いくらラースでも、さすがにそれは用意できないですよねー"},"kind":"dialogue"},{"uid":"talk.ch22_2_1111#originalText","id":"talk.ch22_2_1111","speaker":{"cn":"诗乃","en":"Shino","ja":"詩乃"},"text":{"cn":"话说回来，这重现度太惊人了……隔着画面看几乎完全一样……","en":"Still, I'm amazed by the recreation they did. You can barely tell the difference through the screen.","ja":"それにしても、凄い再現度だわ……画面越しだと、ほとんど違いが……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1112#originalText","id":"talk.ch22_2_1112","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在现实世界名为《记者会》的场合上，等待着我的是毫不留情的提问。","en":"At this Real World ritual called a \"press conference,\" a slew of blunt questions awaited me.","ja":"リアルワールドでの《記者会見》とやらで私を待っていたのは無遠慮な問いだった"},"kind":"dialogue"},{"uid":"talk.ch22_2_1113#originalText","id":"talk.ch22_2_1113","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"他们与桐人、亚丝娜等……先前来帮助我们的现实世界人截然不同。","en":"The people there were...completely unlike Kirito, Asuna, and their comrades who came to save us.","ja":"キリトや、アスナや……私たちを助けに来てくれたリアルワールド人とはまったく違う"},"kind":"dialogue"},{"uid":"talk.ch22_2_1114#originalText","id":"talk.ch22_2_1114","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"一字一句里都传达着一种思维──打从一开始就认为我是比他们低级的存在。","en":"It was clear from their tone and words that they perceive me as an inferior existence.","ja":"最初から、私を自分たちより下位の存在だと思っているのが、言葉の端々から伝わってくる"},"kind":"dialogue"},{"uid":"talk.ch22_2_1115#originalText","id":"talk.ch22_2_1115","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"神代博士将我的存在视为人类，并且似乎正在向大家说明，希望大家能比照办理。","en":"Dr. Kojiro sees me as a human and she tried to make everyone come around to her side.","ja":"神代博士は、私の存在を人間と認め皆にもそうするよう説明してくれているようだった"},"kind":"dialogue"},{"uid":"talk.ch22_2_1116#originalText","id":"talk.ch22_2_1116","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"她也告诉大家，在我的世界──也就是他们所说的虚拟世界中，我们和现实世界人是一模一样的。","en":"She even asserted that the virtual world that I'm from is the same as the real world.","ja":"さらに、仮想世界――私の世界はそう呼ばれているでは、我々とリアルワールド人は同じである、とも"},"kind":"dialogue"},{"uid":"talk.ch22_2_1117#originalText","id":"talk.ch22_2_1117","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"然而，这些人打从一开始就将我视为他们的附属物，对这种人，再怎么苦心劝说都是枉然。","en":"But what she said meant nothing to an audience who perceived me to be dependent on them.","ja":"だが、最初から私を自分たちの従属物だと考える輩には、いくら言葉を尽くしても意味はなかった"},"kind":"dialogue"},{"uid":"talk.ch22_2_1118#originalText","id":"talk.ch22_2_1118","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"面对失礼的发言，我也毋须以礼相待。","en":"So, since there was no respect in the words they chose, none was needed in mine either.","ja":"礼を失した発言に、こちらが礼を尽くす必要はない"},"kind":"dialogue"},{"uid":"talk.ch22_2_1119#originalText","id":"talk.ch22_2_1119","speaker":{"cn":"记者","en":"Journalist","ja":"ジャーナリスト"},"text":{"cn":"他们的存在和我们人类实在有太大的差异！","en":"But their existence is too different from ours!","ja":"彼らは、あまりにも私たち人間と存在のありようが違いすぎます!"},"kind":"dialogue"},{"uid":"talk.ch22_2_1120#originalText","id":"talk.ch22_2_1120","speaker":{"cn":"记者","en":"Journalist","ja":"ジャーナリスト"},"text":{"cn":"明明是人类创造的机械，要我们怎么承认他们也一样是人类呢？","en":"How can we possibly acknowledge man-made machines as being the same as humankind?","ja":"人間によって創り出された機械をどうすれば同じ人類と認められるというのですか"},"kind":"dialogue"},{"uid":"talk.ch22_2_1121#originalText","id":"talk.ch22_2_1121","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我承认也接受你们现实世界人是我们的创造者。","en":"I acknowledge and accept the fact of you real-worlders as our creators.","ja":"あなたがたリアルワールド人が、私たちの創造者であることを私は認め、受け入れています"},"kind":"dialogue"},{"uid":"talk.ch22_2_1122#originalText","id":"talk.ch22_2_1122","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"也很感谢你们让我们诞生。","en":"I am grateful to you for creating us.","ja":"生み出してくれたことに感謝もしています"},"kind":"dialogue"},{"uid":"talk.ch22_2_1123#originalText","id":"talk.ch22_2_1123","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"但是，过去和我出生在同个世界的人曾经这么说过──","en":"But as another person born in my world once said...","ja":"しかし、かつて、私と同じ世界に生まれたひとりの人間はこう言いました"},"kind":"dialogue"},{"uid":"talk.ch22_2_1124#originalText","id":"talk.ch22_2_1124","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"──如果现实世界也是被创造出来的世界呢？如果其外侧也存在更高级的创造者呢？","en":"\"What if the real world were also created by others? What if even more creators created them?\"","ja":"――リアルワールドもまた、創られた世界だったら?その外側に、さらなる創造者が存在していたとしたら?"},"kind":"dialogue"},{"uid":"talk.ch22_2_1125#originalText","id":"talk.ch22_2_1125","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果说有一天，你们的创造者现身，命令你们成为奴隶，你们会怎么做？","en":"If, one day, your own creators appeared and ordered you into slavery, what would you do?","ja":"もしもある日、あなた方の創造者が姿を現し隷属せよと命じたらあなた方はどうしますか?"},"kind":"dialogue"},{"uid":"talk.ch22_2_1126#originalText","id":"talk.ch22_2_1126","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是双手撑地宣示忠诚，然后乞求对方的慈悲吗？","en":"Would you grovel on the ground, pledge your loyalty, and beg for mercy?","ja":"地に手を突き、忠誠を誓い、慈悲を乞いますか?"},"kind":"dialogue"},{"uid":"talk.ch22_2_1127#originalText","id":"talk.ch22_2_1127","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我……已经和许多现实世界人交流过。","en":"I have already had many interactions with real-worlders.","ja":"……私は、すでに多くのリアルワールド人たちと交流を重ねています"},"kind":"dialogue"},{"uid":"talk.ch22_2_1128#originalText","id":"talk.ch22_2_1128","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"他们鼓励只身处于陌生世界的我，让我打起了精神。","en":"I am all alone in a strange world, but they've encouraged and supported me.","ja":"見知らぬ世界でひとりぼっちの私を、彼らは励まし元気付けてくれました"},"kind":"dialogue"},{"uid":"talk.ch22_2_1129#originalText","id":"talk.ch22_2_1129","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"教会我很多事物，也带我到很多地方去。我很喜欢他们。","en":"They've taught me many things and taken me to many places. I am very fond of them.","ja":"色々なことを教え、色々な場所を案内してくれました私は彼らが好きです"},"kind":"dialogue"},{"uid":"talk.ch22_2_1130#originalText","id":"talk.ch22_2_1130","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"而且不只是这样……我甚至爱着一名现实世界人。","en":"And that's not all... I even love one of those real-worlders.","ja":"それだけではない……ひとりのリアルワールド人を私は愛してすらいます"},"kind":"dialogue"},{"uid":"talk.ch22_2_1131#originalText","id":"talk.ch22_2_1131","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"一想到现在无法见面的那个人……钢铁制的胸口都像要裂开一样……","en":"Whenever I think of this person, whom I'm unable to see now... even this steel chest aches.","ja":"いまは会えないその人のことを考えると……この、鋼の胸ですら張り裂けそうなほどに……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1132#originalText","id":"talk.ch22_2_1132","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我……拥有对你们现实世界人伸出的右手。","en":"I have a right hand that I will extend to the people of the real world.","ja":"……私は、あなた方リアルワールドの人々に向けて差し出す右手は持っています"},"kind":"dialogue"},{"uid":"talk.ch22_2_1133#originalText","id":"talk.ch22_2_1133","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"但是，没有跪在地上的膝盖和平伏的额头……因为我也是人类。","en":"But I will not fall to my knees or grind my forehead in the dirt. That's because I am a human.","ja":"しかし、地に突く膝と、平伏する額は持っていないなぜなら私は、人間だからです"},"kind":"dialogue"},{"uid":"talk.ch22_2_1134#originalText","id":"talk.ch22_2_1134","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"记者会途中，我感觉到一股气息。一股十分怀念……十分珍视的气息……","en":"During the conference, I sensed a certain presence. A very familiar...beloved presence.","ja":"会見の途中、私はある気配を感じたとても懐かしく……愛おしい気配を……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1135#originalText","id":"talk.ch22_2_1135","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我向众人表示我有急事，随后离开现场。","en":"I told them that I suddenly had something very important to do and left the venue.","ja":"私は、急用ができた旨を告げその場を後にした"},"kind":"dialogue"},{"uid":"talk.ch22_2_1136#originalText","id":"talk.ch22_2_1136","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"因为对我而言，世上再没有比他的苏醒更为重要的事了。","en":"Because to me, there is no event more important than his awakening.","ja":"私にとって、彼の目覚めより大事なことなど世界のどこにもないのだから"},"kind":"dialogue"},{"uid":"talk.ch22_2_1201#originalText","id":"talk.ch22_2_1201","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"电视画面上映照出菊先生的照片，旁边字幕写着「事件的唯一牺牲者」。","en":"Mr. Kiku's photo was on TV with the caption, \"the lone casualty of this tragedy.\"","ja":"テレビ画面では、「事件のたったひとりの犠牲者」として菊さんの写真が映し出されている"},"kind":"dialogue"},{"uid":"talk.ch22_2_1202#originalText","id":"talk.ch22_2_1202","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"而那位菊先生本人此刻却身穿夏威夷衫站在我旁边看着电视。","en":"Even though Mr. Kiku was actually right next to me, in a Hawaiian shirt, watching the screen.","ja":"当の菊さんは、アロハシャツなんか着て僕の隣でテレビを見ているのに"},"kind":"dialogue"},{"uid":"talk.ch22_2_1203#originalText","id":"talk.ch22_2_1203","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"据菊先生所言，这好像是「最好的方法」……","en":"According to him, this had been the best option to take.","ja":"菊さん曰く「これが最善の手」なんだそうで……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1204#originalText","id":"talk.ch22_2_1204","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"记者们的提问大致都在预料之中，就在我对记者会感到些许厌倦时……","en":"And just as we were getting sick of the press conference with the expected array of rude questions...","ja":"記者たちの質問もおおかた予想通りでいささか会見に飽きてきた頃……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1205#originalText","id":"talk.ch22_2_1205","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"桐人小弟和亚丝娜小姐的摇光产生了反应。","en":"...there was a pulse in Kirito and Asuna's fluctlights.","ja":"キリト君とアスナさんのフラクトライトに反応が起きた"},"kind":"dialogue"},{"uid":"talk.ch22_2_1206#originalText","id":"talk.ch22_2_1206","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"理论上，再次苏醒的可能性极其趋近于零……","en":"Theoretically, the chances of them reviving were close to zero.","ja":"理論上、再覚醒する可能性は限りなくゼロに近い……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1207#originalText","id":"talk.ch22_2_1207","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"即便如此，我还是可以期待一下吧？正当我这么想的时候──","en":"And just when I was starting to wonder if it was okay to get my hopes up in spite of this...","ja":"それでも、期待していいのだろうか?そんなことを考えていると――"},"kind":"dialogue"},{"uid":"talk.ch22_2_1208#originalText","id":"talk.ch22_2_1208","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……桐人！","en":"Kirito!","ja":"……キリトっ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_1209#originalText","id":"talk.ch22_2_1209","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"爱……爱丽丝！？","en":"A-Alice?!","ja":"あ……アリス!?"},"kind":"dialogue"},{"uid":"talk.ch22_2_1210#originalText","id":"talk.ch22_2_1210","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"………………","en":"......"},"kind":"dialogue"},{"uid":"talk.ch22_2_1211#originalText","id":"talk.ch22_2_1211","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……嗨，爱丽丝，好久不见了。","en":"...Hey, Alice. Long time no see.","ja":"……やあ、アリス久しぶりだね"},"kind":"dialogue"},{"uid":"talk.ch22_2_1212#originalText","id":"talk.ch22_2_1212","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人……呜、呜呜……","en":"Kirito... Uh...Ugh...","ja":"キリト……うっ、うう……"},"kind":"dialogue"},{"uid":"talk.ch22_2_1213#originalText","id":"talk.ch22_2_1213","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"爱丽丝，妳的妹妹赛鲁卡选择了处于Deep freeze状态来等待妳回去。","en":"Alice. Your little sister, Selka, chose to go into Deep Freeze to wait for your return.","ja":"アリス。君の妹セルカはディープ・フリーズで君の帰りを待つ道を選んだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_1214#originalText","id":"talk.ch22_2_1214","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"现在依然在中央圣堂第80层，那座山丘上沉睡着。","en":"On the 80th floor of the Central Cathedral, she's still asleep even now on top of that hill.","ja":"セントラル・カセドラル80階あの丘の上で、今も眠りについている"},"kind":"dialogue"},{"uid":"talk.ch22_2_1215#originalText","id":"talk.ch22_2_1215","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……！","en":"Oh!","ja":"……っ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_1216#originalText","id":"talk.ch22_2_1216","speaker":{"cn":"桐人","en":"Kirito"},"text":{"cn":"呜呜……","en":"Ohh..."},"kind":"dialogue"},{"uid":"talk.ch22_2_1217#originalText","id":"talk.ch22_2_1217","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"来吧，比嘉先生。","en":"All right, Mr. Higa, go ahead.","ja":"さあ、比嘉さん"},"kind":"dialogue"},{"uid":"talk.ch22_2_1218#originalText","id":"talk.ch22_2_1218","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"将我们界限加速阶段开始后的两百年份的记忆删除掉吧。","en":"Delete the memories of the last 200 years since the start of the max-acceleration phase.","ja":"限界加速フェーズが始まってからの200年分の記憶をデリートしてくれ"},"kind":"dialogue"},{"uid":"talk.ch22_2_1219#originalText","id":"talk.ch22_2_1219","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我和王妃的任务已经结束了。","en":"My and the queen's roles are done.","ja":"俺と王妃の役目は、もう終わった"},"kind":"dialogue"},{"uid":"talk.ch22_2_2101#originalText","id":"talk.ch22_2_2101","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"每当在病房里醒来，便有一股困惑感袭来。心想着「这里究竟是哪里？」","en":"When I awake in my hospital bed, I am attacked by the feeling that something was off.","ja":"病室で目が覚めると、違和感に襲われるいったいここはどこだったのだろうか、と"},"kind":"dialogue"},{"uid":"talk.ch22_2_2102#originalText","id":"talk.ch22_2_2102","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"但是，这种不对劲的感觉也随着时间慢慢变淡了。","en":"But this strange feeling grows weaker by the day.","ja":"だが、その違和感も日に日に薄れていく"},"kind":"dialogue"},{"uid":"talk.ch22_2_2103#originalText","id":"talk.ch22_2_2103","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"想回到那个世界的思乡念头也将迎来淡忘之时了吧。","en":"I wonder if my homesickness for Underworld...will eventually fade, too?","ja":"あの世界に還りたい、という望郷の念も消えてなくなる時が来るんだろうか"},"kind":"dialogue"},{"uid":"talk.ch22_2_2104#originalText","id":"talk.ch22_2_2104","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"那天，亚丝娜来探望我。","en":"Asuna came to see me that day.","ja":"その日は、アスナがお見舞いに来てくれた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2105#originalText","id":"talk.ch22_2_2105","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我告诉她出院的日期后，她开心极了，兴奋地说非好好庆祝不可。","en":"When I told her my discharge date, she got all excited and started planning a party.","ja":"退院の日取りを伝えると、大喜びでお祝いをしなくちゃ、とはしゃいでいた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2106#originalText","id":"talk.ch22_2_2106","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"亚丝娜一在我身旁坐下，便唤起了我在Underworld的记忆。","en":"Then, as she sat next to me, my memories from Underworld started to flood back.","ja":"アスナが隣に座ると、アンダーワールドでの記憶が甦ってくる"},"kind":"dialogue"},{"uid":"talk.ch22_2_2107#originalText","id":"talk.ch22_2_2107","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"罗妮耶、缇洁、莉娜学姊……以及黑暗界的伊斯卡恩……","en":"Ronie, Tiese, Liena... and Iskahn from the Dark Realm.","ja":"ロニエや、ティーゼ、リーナ先輩……そして、暗黒界のイスカーン……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2108#originalText","id":"talk.ch22_2_2108","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"但到人界与黑暗界和谈成立那天开始，我的记忆就中断了。","en":"But my memory cut out at the part where the Human Empire and Dark Realm achieved peace.","ja":"だが、人界と暗黒界の和平が為ったところで俺の記憶は途切れている"},"kind":"dialogue"},{"uid":"talk.ch22_2_2109#originalText","id":"talk.ch22_2_2109","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"下一个有印象的……是记忆消除后比嘉先生呼唤我的场景。","en":"Where my memory picks up after that is Mr. Higa calling my name after our memories were deleted.","ja":"次に覚えているのは、記憶を消去してもらった後比嘉さんに声をかけられたことだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2110#originalText","id":"talk.ch22_2_2110","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"在Underworld的时间里，那些和我一同生活过的人们都已经不在了吧？","en":"The people I shared my life with in Underworld...are probably no longer alive.","ja":"アンダーワールドの時間では、もう共に過ごした人たちは生きていないだろう"},"kind":"dialogue"},{"uid":"talk.ch22_2_2111#originalText","id":"talk.ch22_2_2111","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"一念至此，眼泪就──","en":"The thought of it makes me cry...","ja":"そう思うと、涙が――"},"kind":"dialogue"},{"uid":"talk.ch22_2_2112#originalText","id":"talk.ch22_2_2112","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"别担心，就算记忆消失了，回忆也不会消失哟。","en":"It's all right. Even if our memories are gone, they'll stay in our hearts forever.","ja":"大丈夫記憶は消えても、思い出は消えないよ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2113#originalText","id":"talk.ch22_2_2113","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"──没错，桐人。不要哭……Stay cool。","en":"That's right, Kirito. Don't cry. Stay cool.","ja":"――そうさ、キリト泣くなよ……ステイ・クール"},"kind":"dialogue"},{"uid":"talk.ch22_2_2114#originalText","id":"talk.ch22_2_2114","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"之后，菊冈先生以探病的名义来到我的病房。","en":"After that, Mr. Kikuoka came to visit me in my hospital room.","ja":"その後、菊岡さんが見舞いと称して俺の病室にやってきた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2115#originalText","id":"talk.ch22_2_2115","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"菊冈先生虽然表面上已经身亡，但似乎仍在台面下从事各种活动。","en":"According to public record, he's dead, but he's still doing a lot of work behind the scenes.","ja":"記録上は死んだことになっている菊岡さんだがそれでもいろいろ裏で動いているらしい"},"kind":"dialogue"},{"uid":"talk.ch22_2_2116#originalText","id":"talk.ch22_2_2116","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"幸好，他看起来也愿意协助保全Underworld。","en":"Fortunately, I know he's also an ally of Underworld and is helping to protect it.","ja":"幸い、彼もアンダーワールドの保全には協力的に見える"},"kind":"dialogue"},{"uid":"talk.ch22_2_2117#originalText","id":"talk.ch22_2_2117","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"在国家正式采取行动之前，让社会舆论偏向承认人工智能们的人权。","en":"Before the government thinks of intervening, we need to get the public to accept the AIs as human.","ja":"国が本格的に動く前に世論を動かして人工知能たちの人権を認めさせる"},"kind":"dialogue"},{"uid":"talk.ch22_2_2118#originalText","id":"talk.ch22_2_2118","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"这似乎就是菊冈先生的对策──倒不如说是希望。","en":"That is Mr. Kikuoka's plan... rather, his hope.","ja":"それが、菊岡さんの策――というより希望、だそうだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2119#originalText","id":"talk.ch22_2_2119","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"这不是一介学生的我可以插手的了，只能把事情托付给他了。","en":"And as a powerless student, my only hope is to put my faith in his plan.","ja":"何もできない、一介の学生である俺にはその策にすがるしか方法がない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2120#originalText","id":"talk.ch22_2_2120","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"Underworld仍是个不稳定的存在，随时都会因为现实世界人的决策而崩坏。","en":"Underworld is in a precarious situation. It could be destroyed any minute by folks in our world.","ja":"アンダーワールドは、未だこちら側の都合でいつでも崩壊してしまう、不安定な存在だ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2121#originalText","id":"talk.ch22_2_2121","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我必须守护它──绝对。","en":"So we must protect it. At any cost.","ja":"それを守らなくては――絶対に"},"kind":"dialogue"},{"uid":"talk.ch22_2_2201#originalText","id":"talk.ch22_2_2201","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"……不可能顺利运转吧。","en":"Of course it's not going to run.","ja":"……うまく動くわけないよな"},"kind":"dialogue"},{"uid":"talk.ch22_2_2202#originalText","id":"talk.ch22_2_2202","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"一定马上就会崩坏吧。我和菊先生的拷贝都是这样。","en":"It's definitely going to collapse right away. That's what happened to both my and Mr. Kiku's copies.","ja":"すぐに崩壊しちゃうに決まってるんだこの僕や、菊さんのコピーだってそうだったんだから"},"kind":"dialogue"},{"uid":"talk.ch22_2_2203#originalText","id":"talk.ch22_2_2203","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"人类被保存在LightCube里的灵魂是绝对无法承受的。","en":"There's no way that a human soul saved onto a lightcube can stand to know it's a copy of itself.","ja":"ライトキューブに保存された人間の魂は絶対に耐えられない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2204#originalText","id":"talk.ch22_2_2204","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"就算……就算他是……","en":"Even...even if it's...","ja":"たとえ……たとえ、それが……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2205#originalText","id":"talk.ch22_2_2205","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……在那里的应该是比嘉先生吧？","en":"This is... Mr. Higa, I presume?","ja":"……そこにいるのはたぶん、比嘉さんかな"},"kind":"dialogue"},{"uid":"talk.ch22_2_2206#originalText","id":"talk.ch22_2_2206","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"是……是啊。","en":"Th-That's right.","ja":"そ……そうッス"},"kind":"dialogue"},{"uid":"talk.ch22_2_2207#originalText","id":"talk.ch22_2_2207","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我没被我删除掉吗？正确来说……应该是被拷贝了吧？","en":"So you didn't delete me. Or to be precise, you've copied me?","ja":"俺を、消さなかったんだな正確には……コピーした、と言うべきか"},"kind":"dialogue"},{"uid":"talk.ch22_2_2208#originalText","id":"talk.ch22_2_2208","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"怎么……怎么可能删除掉呢！！","en":"I couldn't...I couldn't delete you!","ja":"消せる……消せるわけ、ないッスよ!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2209#originalText","id":"talk.ch22_2_2209","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"你是第一个撑过两百年时光的摇光！","en":"You're the first fluctlight to survive the passage of 200 years!","ja":"君は、200年という時間に耐え抜いた初のフラクトライトなんだ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2210#originalText","id":"talk.ch22_2_2210","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"不对……是人类史上活了最长时间的人了！","en":"No, you're the longest-living person in human history!","ja":"いや……人類史上もっとも長い時間を生きた人間になってしまったんだ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2211#originalText","id":"talk.ch22_2_2211","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"怎么可以把你删除掉呢……你说对吧，桐人小弟！！","en":"I could never delete you. Isn't that right, Kirito?!","ja":"消去できるわけない……そうだろ、キリト君!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2212#originalText","id":"talk.ch22_2_2212","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……我早就预料到会有这种事情了。","en":"I had a feeling that something like this might happen.","ja":"……こういうこともあるかと予想はしていた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2213#originalText","id":"talk.ch22_2_2213","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……比嘉先生，你只拷贝了我的摇光吗？","en":"Mr. Higa, was my fluctlight the only one you copied?","ja":"……比嘉さんコピーしたのは、俺のフラクトライトだけか?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2214#originalText","id":"talk.ch22_2_2214","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"嗯……是啊。","en":"Y-Yeah.","ja":"あ……ああ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2215#originalText","id":"talk.ch22_2_2215","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"在消除记忆的操作中，要瞒过菊冈二佐与神代博士的目光来进行拷贝作业，","en":"During the memory-deleting operation, yours was the only one I managed to copy...","ja":"記憶消去オペレーション中に、菊岡二佐や神代博士の目を盗んで複製作業するのは"},"kind":"dialogue"},{"uid":"talk.ch22_2_2216#originalText","id":"talk.ch22_2_2216","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"光是拷贝你一个人就是我的极限了。","en":"...behind Lt. Colonel Kikuoka's and Dr. Kojiro's backs.","ja":"君ひとりぶんが限界だったんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2217#originalText","id":"talk.ch22_2_2217","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样啊……","en":"I see.","ja":"そうか……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2218#originalText","id":"talk.ch22_2_2218","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我曾和王妃……和亚丝娜说过──如果出现这种情况该怎么办。","en":"Her Majesty...Asuna and I discussed this. What we would do if something like this happened.","ja":"王妃と……アスナと話したことがある仮にこのような状況に至ったらどうするか、と"},"kind":"dialogue"},{"uid":"talk.ch22_2_2219#originalText","id":"talk.ch22_2_2219","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"亚丝娜表示──如果被拷贝的只有她，她会立刻请求把拷贝删除。","en":"This is what Asuna told me: If she were the only one who got copied, she would delete herself.","ja":"アスナは言った。複製されたのが自分ひとりだったら、即座に消去して貰う"},"kind":"dialogue"},{"uid":"talk.ch22_2_2220#originalText","id":"talk.ch22_2_2220","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"如果两个人都被拷贝，就把所剩不多的时间用在融合现实世界与Underworld上……","en":"If both of us were copied, then we would work to unite the real world and Underworld.","ja":"ふたりだったら、残り少ない時間を、リアルワールドとアンダーワールドの融和に使いましょう、とね……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2221#originalText","id":"talk.ch22_2_2221","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"那么……只有你一个人的话呢？那时候该怎么办？","en":"Then, if you were the only one? What would you do then?","ja":"なら、君ひとりの場合は?その時はどうすると?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2222#originalText","id":"talk.ch22_2_2222","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"到时我会只为了Underworld而战。因为我……是那个世界的守护者。","en":"In that case, I would fight only for Underworld. Because I am the protector of that world.","ja":"その時は、アンダーワールドのためにのみ戦うなぜなら俺は……あの世界の守護者なのだから"},"kind":"dialogue"},{"uid":"talk.ch22_2_2223#originalText","id":"talk.ch22_2_2223","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"为了……Underworld而战？","en":"F-Fight?","ja":"た……戦う?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2224#originalText","id":"talk.ch22_2_2224","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"Underworld目前处于非常不安定的状况。","en":"The situation Underworld is currently in is extremely unstable.","ja":"アンダーワールドは現在非常に不安定な状況に置かれている"},"kind":"dialogue"},{"uid":"talk.ch22_2_2225#originalText","id":"talk.ch22_2_2225","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我没说错吧？","en":"Isn't that right?","ja":"そうだろう?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2226#originalText","id":"talk.ch22_2_2226","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"确实……是如此……","en":"Yeah...that's true.","ja":"確かに……そうッスけど……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2227#originalText","id":"talk.ch22_2_2227","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那个世界面对现实世界，可以说是无力到令人伤心。","en":"Compared to the real world, that world is tragically powerless.","ja":"あの世界は、リアルワールドにあっては悲しいほどに無力だ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2228#originalText","id":"talk.ch22_2_2228","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"能源、硬件、保养以及网络……","en":"Energy, hardware, maintenance, and networking...","ja":"エネルギー、ハードウェア、メンテナンスそしてネットワーク……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2229#originalText","id":"talk.ch22_2_2229","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"所有公共建设的维持与管理都得依存现实世界的人类。","en":"We have to depend on the people of the real world to keep the infrastructure operating.","ja":"あらゆるインフラの保守管理を現実世界の人間に依存せざるを得ない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2230#originalText","id":"talk.ch22_2_2230","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样实在无法获得长期的安全保障。","en":"That doesn't bode well for its long-term safety.","ja":"それでは、とても長期的な安全は保証されない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2231#originalText","id":"talk.ch22_2_2231","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"但是那也没办法啊。","en":"But there's no way around that, though.","ja":"しかし、それはどうしようもないことッスよ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2232#originalText","id":"talk.ch22_2_2232","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"Underworld的实体，LightCube Cluster是无法移出Ocean Turtle的。","en":"Underworld's physical appearance, the Lightcube cluster, can't be moved off the Ocean Turtle.","ja":"アンダーワールドの実体、ライトキューブクラスターはオーシャン・タートルから動かすことはできないんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2233#originalText","id":"talk.ch22_2_2233","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"而且那艘船目前的国家管理下，只要国家做出决定……","en":"Not to mention, the ship's under government control now.","ja":"そしてあの船は、今は国の管理下にある国の決定いかんでは……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2234#originalText","id":"talk.ch22_2_2234","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"甚至明天就可能关闭电力，Cluster也会整个遭到格式化……","en":"The government could cut off all power tomorrow, and the entire cluster would be reinitialized.","ja":"明日にも電力が落とされ、クラスターが丸ごと初期化されちまうことだってあり得る……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2235#originalText","id":"talk.ch22_2_2235","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"核子反应炉的核燃料可以撑多久？","en":"How long will the nuclear reactor's fuel last?","ja":"原子炉の核燃料はどれくらい持つ?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2236#originalText","id":"talk.ch22_2_2236","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"呃……嗯，那本来是核子潜艇用的压水反应炉……","en":"Um...well, since it's a pressurized water reactor for a nuclear sub...","ja":"え……ええっと、あれはもともと原潜用の加圧水型ッスから……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2237#originalText","id":"talk.ch22_2_2237","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"只维持Cluster的话，4、5年大概没问题……","en":"...if it's only maintaining the cluster, four or five years, maybe?","ja":"クラスターを維持するだけならたぶんあと4、5年は……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2238#originalText","id":"talk.ch22_2_2238","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样的话，原则上……这段期间不需要补给燃料。","en":"Then basically, there'd be no need to refuel during that time.","ja":"ならば、原則的には、その期間は燃料を補給する必要はない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2239#originalText","id":"talk.ch22_2_2239","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"也就是说，只要防止外界的干扰，Underworld就能继续存在对吧？","en":"In other words, as long as we can prevent any outside interference, Underworld will be saved. Correct?","ja":"つまり、外部の干渉さえ防げばアンダーワールドは存続できる。そうだろう?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2240#originalText","id":"talk.ch22_2_2240","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"但、但是……你说防止……Ocean Turtle上面没有任何武器啊！","en":"B-But, if you're trying to protect it, there isn't a weapons system on board the Ocean Turtle.","ja":"で、でも……防ぐと言っても……オーシャン・タートルには武装の類いは一切ないんスよ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2241#originalText","id":"talk.ch22_2_2241","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我说过要战斗了。","en":"I said that I would fight.","ja":"俺は、戦うと言った"},"kind":"dialogue"},{"uid":"talk.ch22_2_2242#originalText","id":"talk.ch22_2_2242","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"战……战斗……？","en":"F-Fight?","ja":"た……戦う……?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2243#originalText","id":"talk.ch22_2_2243","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"但是……现在卫星线路被阻断，无法跟Ocean Turtle通信……","en":"But the satellite connection been cut off, and there's no way to contact the Ocean Turtle.","ja":"けど……今は衛星回線も遮断されてオーシャン・タートルには通信することも"},"kind":"dialogue"},{"uid":"talk.ch22_2_2244#originalText","id":"talk.ch22_2_2244","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"线路是有的，应该有才对。","en":"There is a connection. There must be.","ja":"回線はあるあるはずだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2245#originalText","id":"talk.ch22_2_2245","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"希兹克利夫……不对，茅场晶彦。我需要那个男人的力量。","en":"Heathcliff...no, Akihiko Kayaba. We need his help.","ja":"ヒースクリフ……いや、茅場晶彦あの男の力が必要だ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2246#originalText","id":"talk.ch22_2_2246","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"首先得找到他才行。比嘉先生……你愿意帮忙吧？","en":"But first, we'll need to find him. Mr. Higa...you'll help, won't you?","ja":"まずは、彼を捜さなければならない比嘉さん……協力してくれるな?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2247#originalText","id":"talk.ch22_2_2247","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"茅……茅场学长……！？他还……活着吗……","en":"K-Kayaba? He's...alive?","ja":"か……茅場、先輩……!?生きて……るのか……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2248#originalText","id":"talk.ch22_2_2248","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"──的确，学长所潜伏的二卫门身躯消失了……","en":"Niemon's body... the vessel Kayaba is inside, it did go missing, but...","ja":"――確かに、先輩が入っていたニエモンのボディは、消えてしまったけど……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2249#originalText","id":"talk.ch22_2_2249","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"茅场晶彦的拷贝跟桐谷和人的拷贝……这两个物……不对，这两个人相遇的话……","en":"A copy of Kayaba and a copy of Kirigaya. If these copies...no, if these people were to meet...","ja":"茅場晶彦のコピーと、そして桐ヶ谷和人のコピーこのふたつ……いや、このふたりが出会ったら"},"kind":"dialogue"},{"uid":"talk.ch22_2_2250#originalText","id":"talk.ch22_2_2250","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"会发生什么事呢？","en":"...what would happen?","ja":"何が起きるんだ?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2251#originalText","id":"talk.ch22_2_2251","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"难道说……我打开了某个很不得了的东西……","en":"Could it be that I've opened Pandora's box?","ja":"もしかしたら……僕は、何か、とんでもないモノの蓋を開けてしまったのでは……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2252#originalText","id":"talk.ch22_2_2252","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"但我好想看看……想知道今后的发展。","en":"I want to see. I want to know what will happen.","ja":"見たいその先を知りたい"},"kind":"dialogue"},{"uid":"talk.ch22_2_2253#originalText","id":"talk.ch22_2_2253","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"……我知道了。","en":"All right.","ja":"……解ったッス"},"kind":"dialogue"},{"uid":"talk.ch22_2_2254#originalText","id":"talk.ch22_2_2254","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"我有几个旧有的管道……会试着把加密后的消息流出去……","en":"I have some old contacts I can reach out to. I'll send out some encrypted messages.","ja":"幾つか、昔のアテがあるッスから……暗号化したメッセージを流してみるッスよ……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2301#originalText","id":"talk.ch22_2_2301","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch22_2_2302#originalText","id":"talk.ch22_2_2302","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"把神圣术的作业写完后再睡午觉吧。","en":"If you're going to take a nap, do it after you're done with your Sacred Arts homework.","ja":"昼寝なら、神聖術の課題を終わらせてからにしなよ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2303#originalText","id":"talk.ch22_2_2303","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"又想抄我的答案了吗？","en":"Are you planning to copy mine again?","ja":"また、僕のを写すつもりかい?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2304#originalText","id":"talk.ch22_2_2304","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"对了，之前你教我的技巧，我稍微做了一些改变。","en":"Hey! I tweaked that skill you taught me the other day a little.","ja":"そうだ、この間教わった技ちょっと工夫してみたんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2305#originalText","id":"talk.ch22_2_2305","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"等一下到修练场去吧。","en":"Let's head to the training hall later.","ja":"あとで修練場に行こうよ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2306#originalText","id":"talk.ch22_2_2306","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，又偷跑出去买零食了对吧！当然也有我的份吧！","en":"Hey, you snuck out again to buy some snacks, didn't you? You got some for me, too, right?","ja":"あっ、また抜け出してお菓子買ってきたんだろ!もちろん、僕の分もあるよな!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2307#originalText","id":"talk.ch22_2_2307","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂，快起来啊，桐人。","en":"Come on, wake up, Kirito.","ja":"ほら、起きろよキリト"},"kind":"dialogue"},{"uid":"talk.ch22_2_2308#originalText","id":"talk.ch22_2_2308","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人……","en":"Kirito.","ja":"キリト……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2309#originalText","id":"talk.ch22_2_2309","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"──！","en":"Hm!","ja":"――ッ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2310#originalText","id":"talk.ch22_2_2310","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"呜、呜呜……","en":"Oh...oh...","ja":"う、うう……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2311#originalText","id":"talk.ch22_2_2311","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"早知道就叫他干脆把所有的记忆都删除了！把我和尤吉欧一起度过的两年半的记忆全都删掉！","en":"I should've had them delete all my memories! The full two and a half years I spent with Eugeo!","ja":"いっそ、全ての記憶を消して貰えばよかった!ユージオと過ごした2年半の記憶の全てを!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2312#originalText","id":"talk.ch22_2_2312","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"跟我说好吗，哥哥？在那个世界里发生过的快乐与悲伤等所有的事情。","en":"Hey, tell me about it. What happened in that world. The good, the bad, everything.","ja":"ね、話して、お兄ちゃんあの世界であった、楽しいこと、悲しいこと、全部"},"kind":"dialogue"},{"uid":"talk.ch22_2_2313#originalText","id":"talk.ch22_2_2313","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch22_2_2314#originalText","id":"talk.ch22_2_2314","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"一开始在深邃森林中央遇见他时，他只是个普通的樵夫。","en":"When I first met him, deep in the forest, Eugeo was just a woodcutter.","ja":"いちばん最初に、深い森の真ん中で出会った時あいつはただの木こりだったんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2315#originalText","id":"talk.ch22_2_2315","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"或许很难相信……","en":"It might be hard to believe, but for three hundred years...","ja":"信じられないと思うけど……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2316#originalText","id":"talk.ch22_2_2316","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"但是三百年来，延续了好几世代的人就为了想要砍倒一棵杉树……","en":"...and over multiple generations, they were trying to cut down a single cedar tree.","ja":"たった1本の杉の木を、300年間何世代もかけて切り倒そうとしてたんだぜ……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2401#originalText","id":"talk.ch22_2_2401","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人……","en":"Kirito.","ja":"キリト……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2402#originalText","id":"talk.ch22_2_2402","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我……好像要枯萎了一样……","en":"I feel...I might wither away.","ja":"私、萎れてしまいそうです……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2403#originalText","id":"talk.ch22_2_2403","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我对小直诉说在Underworld的事情。隔天早上，我被一通电话吵了起来。","en":"I opened up to Sugu about my life in Underworld. The next morning, I woke to a phone call.","ja":"スグにアンダーワールドのことを語った次の日の朝、俺は一本の電話で起こされた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2404#originalText","id":"talk.ch22_2_2404","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"「爱丽丝失踪了」这几个字用来唤醒睡眠不足的脑袋很有效。","en":"\"Alice is missing.\" Those words were enough to jolt me from even a deep slumber.","ja":"アリスが失踪した、というその言葉は寝不足の頭が覚醒するのに十分だった"},"kind":"dialogue"},{"uid":"talk.ch22_2_2405#originalText","id":"talk.ch22_2_2405","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"正当我赶忙要前往RATH时，玄关的门铃响了。","en":"Just when I was about to hurry over to Rath, my doorbell rang.","ja":"急いでラースへ向かおうとしたその時玄関のチャイムが鳴った"},"kind":"dialogue"},{"uid":"talk.ch22_2_2406#originalText","id":"talk.ch22_2_2406","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"莫非是爱丽丝……虽然这么想着，但她怎么可能用走的来这里？","en":"At first, I thought it was Alice... but then I realized she couldn't have come here on foot.","ja":"まさか、アリスが……思ったが、彼女が歩いてここまで来られるわけがない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2407#originalText","id":"talk.ch22_2_2407","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"结果按门铃的是宅急便大哥哥。","en":"It was a delivery man.","ja":"チャイムを鳴らしたのは、宅配便のお兄さんだった"},"kind":"dialogue"},{"uid":"talk.ch22_2_2408#originalText","id":"talk.ch22_2_2408","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"包裹是电器制品，寄件人是RATH……如此一来，里面就是装了与Underworld有关的东西吧……？","en":"The package was from Rath. It was electronics. Maybe related to Underworld somehow?","ja":"届け物は、電気製品。送り主はラースならば、アンダーワールドに関わるものなのか……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2409#originalText","id":"talk.ch22_2_2409","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我小心翼翼地打开箱子，然后箱子里伸出一只手抓住我的手腕。","en":"I cautiously opened the box... and a hand reached out from inside, grabbing my wrist.","ja":"恐る恐る箱を開けた俺は、中から伸びてきた腕に手首を捕まれた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2410#originalText","id":"talk.ch22_2_2410","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我不禁叫出了声，这时从箱子里传来一声熟悉的呼唤。","en":"As I yelled out in surprise, I heard a familiar voice, calling me from inside the box.","ja":"思わず悲鳴を上げる俺に、箱の中から聞き覚えのある声が呼びかけてきた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2411#originalText","id":"talk.ch22_2_2411","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"别大吵大闹，可不可以快点把我拉出来啊，桐人？","en":"Would you kindly stop making such a scene and pull me out of here, Kirito?","ja":"騒いでいないで、早く引っ張り出してくれませんか、キリト"},"kind":"dialogue"},{"uid":"talk.ch22_2_2412#originalText","id":"talk.ch22_2_2412","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我在一头雾水的状况下带爱丽丝进到屋里。","en":"And then, thoroughly confused, I brought Alice inside.","ja":"状況を整理できないまま、アリスを部屋に上げる"},"kind":"dialogue"},{"uid":"talk.ch22_2_2413#originalText","id":"talk.ch22_2_2413","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"原来爱丽丝自行准备了箱子、安排好寄件的手续，花了两天的时间才来到我家。","en":"Alice had packed herself in the box and spent the last two days on a delivery truck.","ja":"アリスは、自分で箱を用意し、発送の手配をして家まで2日かけてやってきたというのだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2414#originalText","id":"talk.ch22_2_2414","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"她说就算征得神代博士的许可来我家，也会有护卫随行。","en":"Even with permission from Dr. Kojiro to visit me, she would have to come with bodyguards.","ja":"神代博士から俺の家に来る許可は貰えてもその時は護衛がついてくる"},"kind":"dialogue"},{"uid":"talk.ch22_2_2415#originalText","id":"talk.ch22_2_2415","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"所以才会用这种像是逃走般的方式……","en":"So she had resorted to these unusual methods to get away.","ja":"だから、こんな逃げ出すような手口を使ったのだ、と……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2416#originalText","id":"talk.ch22_2_2416","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"但是我无论如何都想争取到这段时间。","en":"I just couldn't wait any longer. I was desperate to speak with you alone, face-to-face.","ja":"私はどうしても、この時間を得たかった"},"kind":"dialogue"},{"uid":"talk.ch22_2_2417#originalText","id":"talk.ch22_2_2417","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"和你……不是用虚假的模样，而是拥有真正肉身的桐人单独面对面交谈的时间。","en":"Not in your virtual form, but as someone with a real body.","ja":"あなたと……仮の姿ではなく、本物の体を持つキリトとふたりきりで向き合い、言葉を交わす時間が"},"kind":"dialogue"},{"uid":"talk.ch22_2_2418#originalText","id":"talk.ch22_2_2418","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.ch22_2_2419#originalText","id":"talk.ch22_2_2419","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人，我觉得很生气。","en":"Kirito...I am angry with you.","ja":"キリト、私は怒っているのです"},"kind":"dialogue"},{"uid":"talk.ch22_2_2420#originalText","id":"talk.ch22_2_2420","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我想……也是。","en":"Yes...I suppose you are.","ja":"そう……だろうな"},"kind":"dialogue"},{"uid":"talk.ch22_2_2421#originalText","id":"talk.ch22_2_2421","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"为什么？为什么……那时你不告诉我，或许再也无法见面了……","en":"Why didn't you tell me that day?","ja":"なぜ。なぜ……あの時、言ってくれなかったのですかもう会えないかもしれないと"},"kind":"dialogue"},{"uid":"talk.ch22_2_2422#originalText","id":"talk.ch22_2_2422","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这或许是永远的别离呢？","en":"That it might be our final farewell?","ja":"これが、永遠の別れになるかもしれないと"},"kind":"dialogue"},{"uid":"talk.ch22_2_2423#originalText","id":"talk.ch22_2_2423","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"长达两百年的时间之壁将把我们分隔在两边，已经再也无法碰面了……","en":"That a wall of 200 years would stand between us, never letting me see you ever again?","ja":"200年という時間の壁に隔てられ再びまみえることはもう叶わないのだと"},"kind":"dialogue"},{"uid":"talk.ch22_2_2424#originalText","id":"talk.ch22_2_2424","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"要是你在《世界尽头的祭坛》简短地告诉我，我就……我就不会自己一个人逃走了！！","en":"If only you'd told me that at the World's End Altar...I would not have fled on my own!","ja":"あの《果ての祭壇》でひとこと言ってくれれば私は……私は、ひとり逃げたりしなかった!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2425#originalText","id":"talk.ch22_2_2425","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我是一名骑士！是注定要战斗的人类！","en":"I am a knight! Someone whose destiny is to fight!","ja":"私は騎士です!戦う定めの人間です!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2426#originalText","id":"talk.ch22_2_2426","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"但是……你为什么选择独自面对那个恐怖的敌人……","en":"So...why did you choose to fight such a dreadful foe all alone?","ja":"なのに……なぜお前はたったひとりであの恐るべき敵に立ち向かうことを選び"},"kind":"dialogue"},{"uid":"talk.ch22_2_2427#originalText","id":"talk.ch22_2_2427","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不希望我站在你的身边呢？","en":"And why didn't you want me by your side?","ja":"その隣に私がいることを望んでくれなかったのですか"},"kind":"dialogue"},{"uid":"talk.ch22_2_2428#originalText","id":"talk.ch22_2_2428","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"对你来说，我……爱丽丝‧辛赛西斯‧萨蒂究竟是什么样的存在呢！！","en":"Who am I, Alice Synthesis Thirty, in your eyes? What am I to you?!","ja":"お前にとって私は……アリス・シンセシス・サーティとは、いったい何なのです!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2429#originalText","id":"talk.ch22_2_2429","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"妳是……我的希望。不只对是我而已……","en":"You're...my hope. And not just my hope, either.","ja":"君は……俺の、希望だ俺にとってだけじゃない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2430#originalText","id":"talk.ch22_2_2430","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"对在那个世界生活、死亡的许多人来说，妳都是无可取代的希望。","en":"For all those scores of people who lived and died in that world, too. You're our irreplaceable hope.","ja":"あの世界で生き、死んでいった沢山の人たちのかけがえのない希望なんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2431#originalText","id":"talk.ch22_2_2431","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"所以我无论如何都想保护，也不想失去妳。想要把希望……延续到未来。","en":"That's why I couldn't bear to lose you. That hope... I wanted to link it to the future.","ja":"だから、どうしても守りたかった。失いたくなかった希望を……未来へ繋げたかった"},"kind":"dialogue"},{"uid":"talk.ch22_2_2432#originalText","id":"talk.ch22_2_2432","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"未来……","en":"The future...","ja":"未来……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2433#originalText","id":"talk.ch22_2_2433","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"未来是以什么样的形式存在？我在这个混沌的现实世界……","en":"What exactly will the future look like? After I've endured the endless loneliness...","ja":"未来とは、どのような形をしているのですか私がこの混沌とした現実世界で"},"kind":"dialogue"},{"uid":"talk.ch22_2_2434#originalText","id":"talk.ch22_2_2434","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"被赋予不自由的钢铁身躯，参加无谓的宴席，然后持续忍耐着无尽的寂寞──","en":"...of living in the chaos of the real world, inside this unwieldy steel-element body...","ja":"不自由な鋼の体に、無為な宴席に、そして尽きることのない寂しさに耐え続けた果てに――"},"kind":"dialogue"},{"uid":"talk.ch22_2_2435#originalText","id":"talk.ch22_2_2435","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"最后到底可以获得什么？","en":"...what could possibly be awaiting me?","ja":"何があるというのです"},"kind":"dialogue"},{"uid":"talk.ch22_2_2436#originalText","id":"talk.ch22_2_2436","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"……抱歉，我现在也还不知道。","en":"Sorry... Even I don't know that yet. But you being here will change the world.","ja":"……ごめん今はまだ、俺にもわからない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2437#originalText","id":"talk.ch22_2_2437","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"但是，妳在这里将让世界逐渐改变，它会被你改变。我相信改变的终点──","en":"You're the one who will change it. And when all is said and done...","ja":"でも、ここに君がいることで、世界は変わっていく君が変えていく。その行き着く先で――"},"kind":"dialogue"},{"uid":"talk.ch22_2_2438#originalText","id":"talk.ch22_2_2438","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"卡迪娜尔、亚多米尼史特蕾达、艾尔多利耶……以及尤吉欧的愿望都一定能够得到回报。","en":"...Cardinal's, Administrator's, Eldrie’s, and Eugeo's hopes will finally be rewarded.","ja":"カーディナルの、アドミニストレータの、エルドリエの……ユージオの願いが報われる時が必ず来ると"},"kind":"dialogue"},{"uid":"talk.ch22_2_2439#originalText","id":"talk.ch22_2_2439","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"我是这么相信的。","en":"I have no doubt of that.","ja":"俺は信じている"},"kind":"dialogue"},{"uid":"talk.ch22_2_2440#originalText","id":"talk.ch22_2_2440","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……得跟凛子博士联系才行。让她太担心也很不好意思。","en":"We must let Dr. Rinko know. It wouldn't do to make her worry so much.","ja":"……凛子博士に連絡しなくてはあまり心配させては、申し訳ありませんから"},"kind":"dialogue"},{"uid":"talk.ch22_2_2441#originalText","id":"talk.ch22_2_2441","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"……嗯，说得也是。","en":"Yeah, good idea.","ja":"……うん、そうだな"},"kind":"dialogue"},{"uid":"talk.ch22_2_2501#originalText","id":"talk.ch22_2_2501","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"……对，她现在冷静下来了。好的，我明白了。","en":"Yes... She's much calmer now. Yes. I understand.","ja":"……ええ、今は落ち着いていますはい、わかりました"},"kind":"dialogue"},{"uid":"talk.ch22_2_2502#originalText","id":"talk.ch22_2_2502","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"好，那我先挂断了。","en":"Bye, then.","ja":"はい、それでは"},"kind":"dialogue"},{"uid":"talk.ch22_2_2503#originalText","id":"talk.ch22_2_2503","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"别担心，她没有生气。她反而觉得对妳很过意不去。","en":"Don't worry. She wasn't mad. Actually, she said she felt bad for you.","ja":"大丈夫、怒ってなかったよそれどころか、申し訳ないって言ってた"},"kind":"dialogue"},{"uid":"talk.ch22_2_2504#originalText","id":"talk.ch22_2_2504","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"然后……她还说妳可以在这里住一晚。","en":"And she said that you can spend the night here.","ja":"それで……今日は一晩ここに泊まってきていいってさ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2505#originalText","id":"talk.ch22_2_2505","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真、真的吗！？","en":"R-Really?!","ja":"ほ、本当ですか!?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2506#originalText","id":"talk.ch22_2_2506","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"对啊。","en":"Yeah.","ja":"ああ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2507#originalText","id":"talk.ch22_2_2507","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"既然这么决定了，你就先带我逛逛这间房子吧。","en":"In that case, I'd like you to show me around this house first.","ja":"そうと決まれば、まずはこのお家を案内してください"},"kind":"dialogue"},{"uid":"talk.ch22_2_2508#originalText","id":"talk.ch22_2_2508","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我还是第一次擅建现实世界的传统建筑物呢。","en":"I've never seen any traditional buildings in the real world before!","ja":"リアルワールドの伝統的建築物を実際に見るのは初めてなのです"},"kind":"dialogue"},{"uid":"talk.ch22_2_2509#originalText","id":"talk.ch22_2_2509","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"嗯，好啊……不过，只不过是很普通的民房，实在没有什么可以看的东西……","en":"Sure...no problem. But it's just a family home, so it's not like there's a lot to see.","ja":"ああ、いいよ……と言っても、ただの民家なんだからあんまり見るものなんてなあ……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2510#originalText","id":"talk.ch22_2_2510","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"……啊，对了。到那边去看看吧。","en":"Oh...that's right. I know where to take you.","ja":"……あ、そうだあそこに行ってみるか"},"kind":"dialogue"},{"uid":"talk.ch22_2_2511#originalText","id":"talk.ch22_2_2511","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这里是……修练场吧？","en":"Is this...a training hall?","ja":"ここは……修練場ですね?"},"kind":"dialogue"},{"uid":"talk.ch22_2_2512#originalText","id":"talk.ch22_2_2512","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"没错，在这里是称作道场。","en":"Yeah. Over here, we call it a dojo, though.","ja":"そうこっちじゃ、道場って言うんだけどね"},"kind":"dialogue"},{"uid":"talk.ch22_2_2513#originalText","id":"talk.ch22_2_2513","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"道场……","en":"Dojo...","ja":"ドージョー……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2514#originalText","id":"talk.ch22_2_2514","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这是……修练用的木剑吧。但是和Underworld的完全不一样。","en":"This is a wooden training sword, right? It's so different from the ones in Underworld.","ja":"これは……修練用の木剣ですねでも、アンダーワールドのものとはずいぶん違う"},"kind":"dialogue"},{"uid":"talk.ch22_2_2515#originalText","id":"talk.ch22_2_2515","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"嗯。这是用竹子所做，设计成就算打中了也不会受到重伤。","en":"Yeah, it's made of bamboo and constructed so it won't injure you if you get hit with it.","ja":"うん。竹でできてて、当たっても大怪我しないように工夫してあるんだ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2516#originalText","id":"talk.ch22_2_2516","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"Underworld的木剑，一个搞不好就会被削掉三成天命。","en":"The training swords in Underworld... they'd knock a third of your life off if you're not careful.","ja":"向こうの木剣は、ヘタすると天命が3割くらい削れたけどな"},"kind":"dialogue"},{"uid":"talk.ch22_2_2517#originalText","id":"talk.ch22_2_2517","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这样啊……这边不存在具即效性的治愈术对吧。","en":"I see... You have no instantaneous healing arts here, after all.","ja":"なるほど……こちらには、即効性の治癒術は存在しないですものね"},"kind":"dialogue"},{"uid":"talk.ch22_2_2518#originalText","id":"talk.ch22_2_2518","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"想要修练剑法一定很辛苦吧……","en":"I suppose that training with the sword must involve quite a lot of work.","ja":"剣の修練にも、大変な苦労が伴うのでしょうね……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2519#originalText","id":"talk.ch22_2_2519","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"啥？做什么……？","en":"Huh? What are you...?","ja":"へ?何を……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2520#originalText","id":"talk.ch22_2_2520","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"那还用说吗，在修练场只能做一件事吧？","en":"Isn't it obvious? What else would one do in a training hall?","ja":"決まっています修練場ですることはひとつしかないでしょう"},"kind":"dialogue"},{"uid":"talk.ch22_2_2521#originalText","id":"talk.ch22_2_2521","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"咦……咦咦！？但是爱丽丝，妳那副身体……","en":"W-What?! But Alice...in that body, you're...","ja":"え……ええっ!?なあアリス、きみ、その体で……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2522#originalText","id":"talk.ch22_2_2522","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不用担心！","en":"No need to hold back!","ja":"気遣い無用!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2523#originalText","id":"talk.ch22_2_2523","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"……！","en":"Oh!","ja":"……っ!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2524#originalText","id":"talk.ch22_2_2524","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"让人想起……在中央圣堂第80层的庭园里和你首次交手的事情。","en":"Well, this brings back memories. Of our fight in the garden on the 80th floor of the Cathedral.","ja":"思い出しますね……カセドラル80階の庭園でお前と初めて剣を交えた時のことを"},"kind":"dialogue"},{"uid":"talk.ch22_2_2525#originalText","id":"talk.ch22_2_2525","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"那个时候被妳痛扁了一顿，但这次可没那么容易了。","en":"You really clobbered me that day. It won't happen again today.","ja":"あんときはコテンパンだったけどな今回はそうはいかないぜ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2526#originalText","id":"talk.ch22_2_2526","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"咿呀啊啊啊啊！！","en":"Yaaah!","ja":"イヤアアアア!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2527#originalText","id":"talk.ch22_2_2527","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"嘿咿咿咿啊啊！！","en":"Hiiiyah!","ja":"セエエエアア!!"},"kind":"dialogue"},{"uid":"talk.ch22_2_2528#originalText","id":"talk.ch22_2_2528","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是我赢了。决胜招式是秘藏奥义《钢铁头槌》。","en":"I win, right? And the winning move was the secret skill, \"Steel Headbutt.\"","ja":"私の勝ちね決まり手は、秘奥義《鋼鉄頭突き》よ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2529#originalText","id":"talk.ch22_2_2529","speaker":{"cn":"和人","en":"Kazuto","ja":"和人"},"text":{"cn":"好痛……我没听过有这种招式……","en":"Ow... I've never heard of that move.","ja":"いっ……そんなワザ、聞いたことない……"},"kind":"dialogue"},{"uid":"talk.ch22_2_2530#originalText","id":"talk.ch22_2_2530","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我刚才创的。","en":"I just created it.","ja":"今作ったの"},"kind":"dialogue"},{"uid":"talk.ch22_2_2531#originalText","id":"talk.ch22_2_2531","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人，我不要紧了。能够在这个世界生活下去。","en":"Kirito, I'll be fine now. I know I can live in this world.","ja":"キリト、私はもう大丈夫この世界で生きていけるわ"},"kind":"dialogue"},{"uid":"talk.ch22_2_2532#originalText","id":"talk.ch22_2_2532","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"只要能挥剑，不论身处何方，我就依然是我。","en":"As long as I can wield a sword, wherever I may be, I will be myself.","ja":"剣を振れる限り、どこにいようと私は私だもの"},"kind":"dialogue"},{"uid":"talk.ch22_2_2533#originalText","id":"talk.ch22_2_2533","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"现在知道了……我的战斗尚未结束。","en":"I've just realized... that my battle isn't over yet.","ja":"今、わかったの……私の戦いは、まだ終わっていない"},"kind":"dialogue"},{"uid":"talk.ch22_2_2534#originalText","id":"talk.ch22_2_2534","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你的战斗也一样。","en":"And neither is yours.","ja":"そして、あなたの戦いも"},"kind":"dialogue"},{"uid":"talk.ch22_2_2535#originalText","id":"talk.ch22_2_2535","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"所以要看着前面，我会只看着前面笔直地前进。","en":"So I will look forward, and only forward, and keep moving ahead.","ja":"だから、前を見て、前だけを見てまっすぐに進んでいくわ"},"kind":"dialogue"}]};
